<script lang="ts">
 import {onMount} from 'svelte';
 import {locale,t} from '$lib/i18n';
 import {statusLabel,importLabel} from '$lib/download-status';
 let {kind='all',overview=false}:{kind?:'all'|'tv'|'movie';overview?:boolean}=$props();
 let data=$state<any>(null),error=$state(''),filter=$state('all'),query=$state(''),busy=$state(false);
 const states=['pending','approved','running','finished'];const names:Record<string,string>={all:'All requests',pending:'Pending',approved:'Approved',running:'In progress',finished:'Finished'};
 let filtered=$derived((data?.requests??[]).filter((r:any)=>(filter==='all'||r.status===filter)&&r.name.toLowerCase().includes(query.toLowerCase())).sort((a:any,b:any)=>states.indexOf(a.status)-states.indexOf(b.status)));
 async function refresh(){try{const r=await fetch('/api/v1/requests/center?kind='+kind);const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Requests could not be loaded.');data=d;error='';}catch(e){error=(e as Error).message;}}
 async function approve(row:any){busy=true;try{const r=await fetch(`/api/v1/requests/center/${row.kind}/${row.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({authorized:true})});if(!r.ok)throw Error('Request could not be approved.');await refresh();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 onMount(()=>{let active=true;void refresh();const timer=setInterval(()=>{if(active&&document.visibilityState==='visible')void refresh();},5000);return()=>{active=false;clearInterval(timer);};});
</script>
<section class="space-y-5" aria-label={t($locale,'Request center')}>
 {#if data}
  {#if overview}<div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{#each states as state}<button onclick={()=>filter=filter===state?'all':state} class="rounded-2xl border bg-card p-5 text-left shadow-sm"><span class="text-sm text-muted-foreground">{t($locale,names[state])}</span><strong class="mt-2 block text-3xl">{data.counts[state]}</strong></button>{/each}</div>{/if}
  {#if !data.is_admin}<div class="flex flex-wrap items-center justify-between gap-3 rounded-2xl border bg-gradient-to-br from-primary/10 to-card p-5"><div><h2 class="font-semibold">{t($locale,'Your request quota')}</h2><p class="mt-1 text-sm text-muted-foreground">{t($locale,'Resets on')} {new Date(data.quota.resets_at).toLocaleString($locale,{dateStyle:'long',timeStyle:'short',timeZone:'Europe/Berlin'})} · Europe/Berlin</p></div><div class="text-right"><strong class="text-2xl">{data.quota.limit==null?t($locale,'Unlimited'):Math.max(0,data.quota.limit-data.quota.used)}</strong><p class="text-sm text-muted-foreground">{t($locale,'requests remaining')} · {data.quota.used} {t($locale,'used')}</p></div></div>{/if}
  <div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-semibold">{t($locale,data.is_admin?'Requests':'Your requests')}</h2><input aria-label={t($locale,'Filter requests')} placeholder={t($locale,'Search…')} bind:value={query} class="min-w-0 rounded-lg border bg-background px-3 py-2 text-sm"/></div>
  <nav class="flex flex-wrap gap-2" aria-label={t($locale,'Request status')}><button aria-pressed={filter==='all'} class="rounded-lg border px-3 py-2 text-sm aria-pressed:bg-primary aria-pressed:text-primary-foreground" onclick={()=>filter='all'}>{t($locale,'All requests')}</button>{#each states as state}<button aria-pressed={filter===state} class="rounded-lg border px-3 py-2 text-sm aria-pressed:bg-primary aria-pressed:text-primary-foreground" onclick={()=>filter=state}>{t($locale,names[state])} · {data.counts[state]}</button>{/each}</nav>
  <div class="grid min-w-0 gap-3 md:grid-cols-2">{#each (overview?filtered.slice(0,8):filtered) as row (row.id)}<article class="min-w-0 space-y-3 rounded-2xl border bg-card p-4 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-2"><h3 class="min-w-0 break-words font-semibold">{row.name}{row.year?' ('+row.year+')':''}</h3><span class="rounded-full bg-muted px-3 py-1 text-xs">{t($locale,names[row.status])}</span></div><p class="text-sm text-muted-foreground">{t($locale,row.kind==='movie'?'Movie':'Season')}{row.season_number!=null?' '+row.season_number:''}{row.episode_number!=null?' · '+t($locale,'Episode')+' '+row.episode_number:''}{#if data.is_admin&&row.requested_by} · {row.requested_by}{/if}</p>
   {#each row.progress as progress}<p class="text-sm">{t($locale,statusLabel(progress.state,4))}</p>{#if progress.phase==='postprocessing'||progress.state==='Completed'}<p class="text-xs text-muted-foreground">{t($locale,importLabel(progress,false))}</p>{/if}{/each}
   {#if row.percent!=null}<div class="flex items-center justify-between text-sm"><span>{t($locale,row.status==='finished'?'In library':'Download progress')}</span><span>{row.percent.toLocaleString($locale,{maximumFractionDigits:1})} %</span></div><div class="h-2 overflow-hidden rounded-full bg-muted" role="progressbar" aria-label={t($locale,'Download progress')} aria-valuemin="0" aria-valuemax="100" aria-valuenow={row.percent}><div class="h-full rounded-full bg-primary" style:width={row.percent+'%'}></div></div>{/if}
   {#if data.is_admin&&row.status==='pending'}<button disabled={busy} onclick={()=>approve(row)} class="rounded-lg bg-primary px-3 py-2 text-sm text-primary-foreground">{t($locale,'Approve request')}</button>{/if}
  </article>{:else}<p class="col-span-full rounded-xl border p-5 text-muted-foreground">{t($locale,'No requests match this selection.')}</p>{/each}</div>
  {#if overview&&filtered.length>8}<p class="text-sm text-muted-foreground">{t($locale,'Open Requests in the sidebar to see all requests.')}</p>{/if}
  {#if overview&&data.is_admin}<section class="space-y-3"><h2 class="text-xl font-semibold">{t($locale,'Active downloads')}</h2><div class="grid gap-3 md:grid-cols-2">{#each data.downloads as job}<article class="rounded-xl border bg-card p-4"><h3 class="break-words text-sm font-semibold">{job.title}</h3><p class="mt-2 text-sm text-muted-foreground">{t($locale,statusLabel(job.state,4))}{job.percent!=null?' · '+job.percent.toLocaleString($locale,{maximumFractionDigits:1})+' %':''}</p></article>{:else}<p class="text-sm text-muted-foreground">{t($locale,'No active downloads.')}</p>{/each}</div></section>{/if}
 {/if}
 {#if error}<p role="alert" class="rounded-xl border border-destructive p-3 text-sm text-destructive">{t($locale,error)}</p>{/if}
</section>
